import{z as r,x as s,o as l,c as p,q as o,j as A,D as e,d as t,s as i,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"长度归一化偏差","description":"","frontmatter":{"title":"长度归一化偏差","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/length-normalization-bias.md","filePath":"llm/length-normalization-bias.md","lastUpdated":1791413859000}'),d={name:"llm/length-normalization-bias.md"};function D(m,a,F,P,h,k){const n=s("Mermaid");return l(),p("div",null,[a[2]||(a[2]=o('<h1 id="长度归一化偏差" tabindex="-1">长度归一化偏差 <a class="header-anchor" href="#长度归一化偏差" aria-label="Permalink to &quot;长度归一化偏差&quot;">​</a></h1><div class="epigraph"><p>把损失或奖励除以长度，看起来在公平对待长短样本，其实在改任务：短错误与长正确的相对权重被重写。</p><footer>—— 对照 Dr. GRPO 对长度偏差的分析；DAPO 用 token 级损失而不是按条平均；GSPO 把比率收到序列级</footer></div><p><a href="/llm/reward-whitening">上一课</a>钉住奖励的仿射尺度。长度仍以另一种方式进目标：按序列平均 log-prob、按 \\(|y|\\) 除奖励、或 GRPO 先对每条做 token 平均再对组平均。缺口是：<strong>这些「归一化」都在引入长度偏差，不是中性的数值稳定。</strong> 本课写清楚三种除法各改了什么。不重推 clip。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/ppo-llm">PPO</a> 按 token 计损失时，长完成贡献更多项。若再对每条除以 \\(|y_i|\\)，则每个长样本的 token 变轻：高质量长链学不够，低质重复长链也罚不透。DAPO 把这一点写成朴素 GRPO 的缺陷，改成分母为组内 token 总数。反过来，若奖励本身随长度涨（RM 爱长），不除长度则策略写到上限。两条偏差方向相反，不能靠同一次除法同时修。</p><p><span class="marginnote">直觉类比：按条平均是「每份卷子一票」——十页的卷子和一行答案的卷子权重一样；按 token 平均是「每个字一票」。选哪种，等于宣布「题」还是「字」是学习的基本单位——这不是数值技巧，是任务定义。</span></p><p>Dr. GRPO 还指出组内标准化与长度纠缠：更长的错误完成可能有不同的 \\(r\\) 方差。GSPO 认为 token 级比率与序列级奖励粒度不一致。本课不展开 GSPO 公式，只把「除以长度」当作必须声明的测度。</p><h3 id="三种除法" tabindex="-1">三种除法 <a class="header-anchor" href="#三种除法" aria-label="Permalink to &quot;三种除法&quot;">​</a></h3><ol><li>损失按样本平均（每条 \\(1/|y_i|\\)）：长度越长，逐步错误越不痛。</li><li>损失按 token 平均（分母 \\(\\sum |y_i|\\)）：每个 token 一票。</li><li>奖励除以 \\(|y|\\)：直接改 \\(R\\)，短正确更香，长证明吃亏。</li></ol><p>选 3 等于把「简洁」写进任务；选 1 常是实现偷懒。评测若按题准确率，训练测度应接近 2，而不是按条。</p><p><span class="marginnote">DPO 对回答求和还是平均 log-prob，同样改长度偏置。本课的逻辑也适用于 <a href="/llm/dpo">DPO</a>，只是没有优势。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>默认（推理 RL、可验证对错）：token 级损失，序列 \\(R\\) 不除长度，长度用显式惩罚或后课过长过滤控制。开放偏好：若金标控长胜率下降，再在 \\(R\\) 上减 \\(\\alpha |y|\\)，α 在控长评测上扫。报告同时给出准确率与平均长度，避免把注水写成进步。</p>',13)),(l(),A(B,null,{default:e(()=>[i(n,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E6%8C%89%E6%9D%A1%201%2F%7Cy%7C%22%5D%20--%3E%20B1%5B%22%E9%95%BF%E9%93%BE%E6%A2%AF%E5%BA%A6%E8%A2%AB%E7%A8%80%E9%87%8A%22%5D%0A%20%20L2%5B%22%E6%8C%89%20token%20%E5%90%88%E8%AE%A1%22%5D%20--%3E%20B2%5B%22%E9%80%90%E6%AD%A5%E9%94%99%E8%AF%AF%E5%90%8C%E7%AD%89%E6%83%A9%E7%BD%9A%22%5D%0A%20%20L3%5B%22R%20%E9%99%A4%E4%BB%A5%E9%95%BF%E5%BA%A6%22%5D%20--%3E%20B3%5B%22%E4%BB%BB%E5%8A%A1%E5%8F%98%E6%88%90%E5%81%8F%E7%9F%AD%22%5D%0A%20%20B2%20--%3E%20CHOOSE%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%9F%9F%E9%BB%98%E8%AE%A4%22%5D%0A%20%20B3%20--%3E%20OPEN%5B%22%E5%BC%80%E6%94%BE%E5%9F%9F%E6%98%BE%E5%BC%8F%E7%AE%80%E6%B4%81%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要在白化、组内 std、长度除法上叠三层隐式缩放。下一课熵塌缩会与「长而重复」一起出现，那是本课测度选错的常见症状。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"策略梯度的期望是在轨迹测度下。按条平均等于每条轨迹一票，不管多长；按 token 等于按生成时间一票。校验器奖励是轨迹级事件，严格对应「每条一票」；但更新是 token 参数，逐步错误需要 token 票。DAPO 的选择是：事件仍是轨迹 \\(R\\)，梯度测度用 token——不自洽但实用。GSPO 选择把重要性比率也改成轨迹级，自洽另一头。知道自己站在哪头，比抄默认超参重要。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一条 32 token 的短链与一条 512 token 的长链犯了同样 8 处错误。按条除 \\(|y|\\) 平均后，长链每处错误的梯度权重是 \\(1/512\\)，短链是 \\(1/32\\)——同样的错误，长链学得轻 16 倍，这就是「高质量长链学不够、低质长链罚不透」的算术来源。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"长度惩罚与「除以长度」同向但非线性不同。软超长塑形（DAPO）只罚尾部，不伤害中等长度的正确证明。")],-1)),a[8]||(a[8]=E("p",null,"两股偏差方向相反、一次除法修不了两头——这个「夹出默认配方」的结构，单独画出来。",-1)),(l(),A(B,null,{default:e(()=>[i(n,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E5%8A%9B%20A%EF%BC%9ARM%20%E7%88%B1%E9%95%BF%EF%BC%8CR%20%E9%9A%8F%E9%95%BF%E5%BA%A6%E6%B6%A8%22%5D%20--%3E%20UP%5B%22%E7%AD%96%E7%95%A5%E5%BE%80%E9%95%BF%E5%86%99%EF%BC%9A%E6%B3%A8%E6%B0%B4%E5%88%B0%E4%B8%8A%E9%99%90%22%5D%0A%20%20F2%5B%22%E5%8A%9B%20B%EF%BC%9A%E6%8C%89%E6%9D%A1%E9%99%A4%20%7Cy%7C%20%E5%B9%B3%E5%9D%87%22%5D%20--%3E%20DOWN%5B%22%E9%95%BF%E9%93%BE%E7%9A%84%E5%AD%A6%E4%B9%A0%E4%BF%A1%E5%8F%B7%E8%A2%AB%E7%A8%80%E9%87%8A%22%5D%0A%20%20UP%20--%3E%20DEF%7B%22%E9%BB%98%E8%AE%A4%E9%85%8D%E6%96%B9%E6%80%8E%E4%B9%88%E5%8F%96%3F%22%7D%0A%20%20DOWN%20--%3E%20DEF%0A%20%20DEF%20--%3E%7C%22%E5%A0%B5%E5%8A%9B%20A%22%7C%20N1%5B%22R%20%E4%B8%8D%E9%99%A4%E9%95%BF%E5%BA%A6%22%5D%0A%20%20DEF%20--%3E%7C%22%E5%A0%B5%E5%8A%9B%20B%22%7C%20N2%5B%22%E6%8D%9F%E5%A4%B1%E6%8C%89%20token%20%E5%90%88%E8%AE%A1%22%5D%0A%20%20N1%20--%3E%20OK%5B%22token%20%E7%BA%A7%E6%8D%9F%E5%A4%B1%20%2B%20%E6%98%BE%E5%BC%8F%E9%95%BF%E5%BA%A6%E6%83%A9%E7%BD%9A%22%5D%0A%20%20N2%20--%3E%20OK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">常见误区：把「除以长度」当成无害的数值稳定技巧。它实际在改任务定义——除一次，短正确与长正确的相对权重就被重写一次。归一化是测度声明，必须写进实验卡，且报告时同时给出平均长度。</span></p><p>产品延迟按 token 计费时，训练测度忽略长度，上线必爆费用。应把费用写成多目标轴，而不是默默除 \\(|y|\\)。数学竞赛要长证明，除长度会打压 R1 类行为。下一课看熵：重复长链既是长度问题也是探索问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按条除长度稀释长链学习；按 token 合计是 DAPO 的默认测度。</li><li>奖励除以 \\(|y|\\) 是改任务，必须有控长金标。</li><li>长度偏差与 RM 爱长是相反的两股力，一次除法修不了两头。</li><li>与白化、组 std 不要叠加重缩放。</li><li>出处：Yu 等 DAPO token 级损失；Liu 等 Dr. GRPO；Zheng 等 GSPO 的粒度论点。</li></ul>',5))])}const O=r(d,[["render",D]]);export{C as __pageData,O as default};
